"""Small pure functions."""


def add(a, b):
    return a + b


def sub(a, b):
    return a - b

import unittest

from mathlib import add, sub


class MathTest(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add(2, 3), 5)

    def test_sub(self):
        self.assertEqual(sub(5, 3), 2)


if __name__ == "__main__":
    unittest.main()
